VALUES
  ('fun', 'FANN-8809937360834', 'Biodance Bio-Collagen Real Deep Mask', 'Biodance - Bio-Collagen Real Deep Mask – hydrogelová pleťová maska. Maska je rozdělena na dvě části (horní a dolní polovina obličeje) a je určena k nočnímu použití, případně k aplikaci po dobu alespoň 3–4 hodin pro intenzivní hydrataci a zvýšení elasticity pleti.', 120.00, 0, 1, 'skincare', 'zpevňující kolagenová maska 1 ks', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/bio-collagen-real-deep-mask/12026/23377","product_id":12026,"variant_id":23377,"ean":"8809937360834","checked_at":"2026-09-21"},"brand":"Biodance","variant_label":"zpevňující kolagenová maska 1 ks","availability_at_check":"InStock","selection_attributes":{"category":["péče o pleť"],"product_type":["zpevňující kolagenová maska"],"needs":["hydratace","zklidnění","regenerace","vrásky a jemné linky","elasticita a zpevnění"],"fragrance_character":["intenzivní"],"key_ingredients":["kyselina hyaluronová","kolagen"]},"diagnostic_questions":["Jaký je typ pleti a je pleť citlivá?","Jaký hlavní problém má produkt řešit?","Jakou texturu a krok rutiny hledáte?","Jsou nějaké složky nebo parfemace, kterým se chcete vyhnout?"]}' AS JSON)),
  ('fun', 'FANN-8809624723119', 'Round Lab Birch Juice Moisturizing Mask', 'Round Lab - Birch Juice Moisturizing Mask – plátýnková maska určená k péči o pleť obličeje. Její složení zahrnuje šťávu z japonské břízy a hyaluronát sodný, které hloubkově hydratují suchou pleť.', 72.00, 0, 1, 'skincare', 'hydratační maska s březovou šťávou 1 ks', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/birch-juice-moisturizing-mask/12037/23388","product_id":12037,"variant_id":23388,"ean":"8809624723119","checked_at":"2026-09-21"},"brand":"Round Lab","variant_label":"hydratační maska s březovou šťávou 1 ks","availability_at_check":"InStock","selection_attributes":{"category":["péče o pleť"],"product_type":["hydratační maska s březovou šťávou"],"target_audience":["citlivá pleť nebo oči"],"needs":["hydratace","zklidnění","regenerace"],"fragrance_character":["svěží"],"key_ingredients":["kyselina hyaluronová"]},"diagnostic_questions":["Jaký je typ pleti a je pleť citlivá?","Jaký hlavní problém má produkt řešit?","Jakou texturu a krok rutiny hledáte?","Jsou nějaké složky nebo parfemace, kterým se chcete vyhnout?"]}' AS JSON)),
  ('fun', 'FANN-8809581454743', 'Missha Airy Fit Sheet Mask Aloe', 'Hydratační plátýnková maska s obsahem aloe vera pro zklidnění podrážděné pleti. Jemná struktura masky perfektně přilne k pleti a zajistí účinné vstřebání aktivních složek.', 44.00, 0, 1, 'skincare', 'plátýnková maska 19 g', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/airy-fit-sheet-mask-aloe/12159/23635","product_id":12159,"variant_id":23635,"ean":"8809581454743","checked_at":"2026-09-21"},"brand":"Missha","variant_label":"plátýnková maska 19 g","availability_at_check":"InStock","selection_attributes":{"category":["péče o pleť"],"product_type":["plátýnková maska"],"needs":["hydratace","zklidnění"],"fragrance_character":["jemná"],"key_ingredients":["aloe vera"]},"diagnostic_questions":["Jaký je typ pleti a je pleť citlivá?","Jaký hlavní problém má produkt řešit?","Jakou texturu a krok rutiny hledáte?","Jsou nějaké složky nebo parfemace, kterým se chcete vyhnout?"]}' AS JSON)),
  ('fun', 'FANN-8809581454781', 'Missha Airy Fit Sheet Mask Pearl', 'Plátýnková maska s rozjasňujícím a hydratačním účinkem. Obsahuje extrakt z perel pro rozjasnění pleti.', 44.00, 0, 1, 'skincare', 'plátýnková maska 19 g', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/airy-fit-sheet-mask-pearl/12155/23631","product_id":12155,"variant_id":23631,"ean":"8809581454781","checked_at":"2026-09-21"},"brand":"Missha","variant_label":"plátýnková maska 19 g","availability_at_check":"InStock","selection_attributes":{"category":["péče o pleť"],"product_type":["plátýnková maska"],"needs":["hydratace","rozjasnění"],"finish_and_effect":["zářivý"]},"diagnostic_questions":["Jaký je typ pleti a je pleť citlivá?","Jaký hlavní problém má produkt řešit?","Jakou texturu a krok rutiny hledáte?","Jsou nějaké složky nebo parfemace, kterým se chcete vyhnout?"]}' AS JSON)),
  ('fun', 'FANN-8809581454798', 'Missha Airy Fit Sheet Mask Shea Butter', 'Výživná plátýnková maska s bambuckým máslem poskytuje suché pleti intenzivní pocit hydratace a komfortu. Jemná celulózová tkanina dokonale přiléhá k pokožce a napomáhá rovnoměrnému vstřebání pečujících složek.', 44.00, 0, 1, 'skincare', 'plátýnková maska 19 g', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/airy-fit-sheet-mask-shea-butter/12156/23632","product_id":12156,"variant_id":23632,"ean":"8809581454798","checked_at":"2026-09-21"},"brand":"Missha","variant_label":"plátýnková maska 19 g","availability_at_check":"InStock","selection_attributes":{"category":["péče o pleť"],"product_type":["plátýnková maska"],"target_audience":["suchá až velmi suchá pokožka"],"needs":["hydratace","výživa","zklidnění"],"fragrance_character":["intenzivní","jemná"],"key_ingredients":["bambucké máslo"]},"diagnostic_questions":["Jaký je typ pleti a je pleť citlivá?","Jaký hlavní problém má produkt řešit?","Jakou texturu a krok rutiny hledáte?","Jsou nějaké složky nebo parfemace, kterým se chcete vyhnout?"]}' AS JSON)),
  ('fun', 'FANN-8809581454750', 'Missha Airy Fit Sheet Mask Tea Tree', 'Zklidňující pleťová maska s obsahem tea tree pomáhá zjemnit podrážděnou pleť a obnovit její rovnováhu. Lehká struktura masky výborně přilne k pleti a podporuje účinné vstřebávání aktivních složek.', 44.00, 0, 1, 'skincare', 'plátýnková maska 19 g', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/airy-fit-sheet-mask-tea-tree/12157/23633","product_id":12157,"variant_id":23633,"ean":"8809581454750","checked_at":"2026-09-21"},"brand":"Missha","variant_label":"plátýnková maska 19 g","availability_at_check":"InStock","selection_attributes":{"category":["péče o pleť"],"product_type":["plátýnková maska"],"target_audience":["citlivá pleť nebo oči"],"needs":["zklidnění","regenerace"],"fragrance_character":["svěží"],"key_ingredients":["tea tree"]},"diagnostic_questions":["Jaký je typ pleti a je pleť citlivá?","Jaký hlavní problém má produkt řešit?","Jakou texturu a krok rutiny hledáte?","Jsou nějaké složky nebo parfemace, kterým se chcete vyhnout?"]}' AS JSON)),
  ('fun', 'FANN-3346470615557', 'Guerlain Abeille Royale Lotion', 'Posilující pleťová voda Fortifying Lotion z řady Abeille Royale má ve svém složení 25x vyšší obsah mateří kašičky* a díky systému mikrokapslí pomáhá pleti odolávat různým stresovým faktorům a znečištění, které viditelně ovlivňují její kvalitu a krásu.Složení je určeno pro všechny typy pleti, dokonce i pro citlivou, Obnovuje pleť tak, aby znovu získala svou optimální rovnováhu, hydrataci, pružnost a zářivost.Den po dni je kožní bariéra více posílena, pleť je odolnější a chráněná před projevy stárnutí. Tento účinn…', 2270.00, 0, 1, 'skincare', 'přípravné lotion 150 ml', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/abeille-royale-lotion/7566/14444","product_id":7566,"variant_id":14444,"ean":"3346470615557","checked_at":"2026-09-21"},"brand":"Guerlain","variant_label":"přípravné lotion 150 ml","availability_at_check":"InStock","selection_attributes":{"category":["péče o pleť"],"product_type":["přípravné lotion"],"target_audience":["citlivá pleť nebo oči"],"needs":["hydratace","regenerace","elasticita a zpevnění","rozjasnění"],"finish_and_effect":["zářivý"],"features":["přírodní původ"],"fragrance_character":["svěží"],"key_ingredients":["mateří kašička"]},"diagnostic_questions":["Jaký je typ pleti a je pleť citlivá?","Jaký hlavní problém má produkt řešit?","Jakou texturu a krok rutiny hledáte?","Jsou nějaké složky nebo parfemace, kterým se chcete vyhnout?"]}' AS JSON)),
  ('fun', 'FANN-3346470615366', 'Guerlain Abeille Royale Multi-Wrinkle Minimizer Eye Cream', 'Oční krém Eye Cream Abeille Royale od Guerlain je vyvinutý specificky na vrásky v očním okolí, od jemných povrchových linek až po hlubší mimické vějířkové vrásky a den po dni pleť viditelně omlazuje. Tento oční krém obsahuje 93 % složek přírodního původu*.', 2920.00, 0, 1, 'skincare', 'oční krém 15 ml', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/abeille-royale-multi-wrinkle-minimizer-eye-cream/7691/14714","product_id":7691,"variant_id":14714,"ean":"3346470615366","checked_at":"2026-09-21"},"brand":"Guerlain","variant_label":"oční krém 15 ml","availability_at_check":"InStock","selection_attributes":{"category":["péče o pleť"],"product_type":["oční krém"],"needs":["hydratace","výživa","regenerace","vrásky a jemné linky","rozjasnění"],"finish_and_effect":["zářivý"],"features":["přírodní původ"],"key_ingredients":["kyselina hyaluronová","mateří kašička","med"]},"diagnostic_questions":["Jaký je typ pleti a je pleť citlivá?","Jaký hlavní problém má produkt řešit?","Jakou texturu a krok rutiny hledáte?","Jsou nějaké složky nebo parfemace, kterým se chcete vyhnout?"]}' AS JSON)),
  ('fun', 'FANN-8011003997008', 'Versace Versense', 'Versense je perfektním propojením svěžesti a smyslnosti. Vůně sama je opojnou oslavou svěžesti inspirovanou silou přírodních živlů a je určená svůdné ženě připravené v životě okusit a vyzkoušet téměř vše.', 2280.00, 0, 1, 'fragrance', 'toaletní voda 30 ml', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/versense/2565/20594","product_id":2565,"variant_id":20594,"ean":"8011003997008","checked_at":"2026-09-21"},"brand":"Versace","variant_label":"toaletní voda 30 ml","availability_at_check":"InStock","selection_attributes":{"category":["vůně"],"product_type":["toaletní voda"],"fragrance_character":["svěží","citrusová","květinová","kořeněná"],"fragrance_notes":["bergamot, zelená mandarinka, plody opuncie","jasmín, kardamom, květ líru","jasmín, kardamom, květ líru"],"concentration":["toaletní voda"]},"diagnostic_questions":["Pro koho vůni vybíráte a jaké vůně běžně používá?","Má být spíše svěží, květinová, sladká, dřevitá, nebo kořeněná?","Je vůně na každý den, večer, konkrétní období, nebo jako dárek?","Jak výraznou vůni a jaký rozpočet preferujete?"]}' AS JSON)),
