  ('fun', 'FANN-6290171074205', 'Zimaya Sharaf Blend', 'Zimaya Sharaf Blend je bohatá orientální vůně, která ztělesňuje smyslnost a eleganci prostřednictvím mistrovské směsi kořenitých, dřevitých a sladkých tónů. Tato unisex vůně je intenzivní a tajemná, což ji činí ideální volbou pro ty, kteří vyhledávají výrazné a dlouhotrvající aroma s exotickým nádechem.', 799.00, 0, 1, 'fragrance', 'parfémový extrakt 100 ml', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/sharaf-blend/11092/21701","product_id":11092,"variant_id":21701,"ean":"6290171074205","checked_at":"2026-09-21"},"brand":"Zimaya","variant_label":"parfémový extrakt 100 ml","availability_at_check":"InStock","selection_attributes":{"category":["vůně"],"product_type":["parfémový extrakt"],"target_audience":["unisex"],"finish_and_effect":["dlouhotrvající"],"fragrance_character":["květinová","dřevitá","orientální","sladká","kořeněná","ambrová","intenzivní","jemná"],"fragrance_notes":["koření, šafrán","růže, kadidlo","dřevité tóny, vanilka, ambra"],"concentration":["parfémový extrakt"]},"diagnostic_questions":["Pro koho vůni vybíráte a jaké vůně běžně používá?","Má být spíše svěží, květinová, sladká, dřevitá, nebo kořeněná?","Je vůně na každý den, večer, konkrétní období, nebo jako dárek?","Jak výraznou vůni a jaký rozpočet preferujete?"]}' AS JSON)),
  ('fun', 'FANN-6290362346531', 'Lattafa Yara Elixir', 'Lattafa Yara Elixir je svůdná a elegantní orientálně-gurmánská vůně pro ženy, která otevírá chuťově sladkou a šťavnatou kompozici jahod a černého rybízu, jež přecházejí do květinově-smyslného srdce a zakončují se teplým, vanilkovo-karamelovým základem. Ideální pro večerní události, romantické chvíle nebo jako výrazná dámská podpisová vůně.', 869.00, 0, 1, 'fragrance', 'parfémová voda 100 ml', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/yara-elixir/12111/23566","product_id":12111,"variant_id":23566,"ean":"6290362346531","checked_at":"2026-09-21"},"brand":"Lattafa","variant_label":"parfémová voda 100 ml","availability_at_check":"InStock","selection_attributes":{"category":["vůně"],"product_type":["parfémová voda"],"target_audience":["ženy"],"fragrance_character":["květinová","ovocná","orientální","gurmánská","sladká","pižmová","ambrová","intenzivní"],"occasion":["večer","romantická příležitost"],"fragrance_notes":["jahoda, černý rybíz","jasmín, pomerančový květ","vanilka, karamel, ambra, pižmo"],"concentration":["parfémová voda"]},"diagnostic_questions":["Pro koho vůni vybíráte a jaké vůně běžně používá?","Má být spíše svěží, květinová, sladká, dřevitá, nebo kořeněná?","Je vůně na každý den, večer, konkrétní období, nebo jako dárek?","Jak výraznou vůni a jaký rozpočet preferujete?"]}' AS JSON)),
