  ('fun', 'FANN-6290362346548', 'Lattafa Asad Elixir', 'Lattaf Asad Elixir je intenzivní orientálně-dřevitá vůně pro muže, který vyzařuje sílu, charisma a sebevědomí. Kompozice propojuje energické kořeněné tóny s bohatým tabákovým srdcem a teplým ambrovým základem pro elegantní a dlouhotrvající stopu.', 869.00, 0, 1, 'fragrance', 'parfémová voda 100 ml', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/asad-elixir/12112/23567","product_id":12112,"variant_id":23567,"ean":"6290362346548","checked_at":"2026-09-21"},"brand":"Lattafa","variant_label":"parfémová voda 100 ml","availability_at_check":"InStock","selection_attributes":{"category":["vůně"],"product_type":["parfémová voda"],"target_audience":["muži"],"finish_and_effect":["dlouhotrvající"],"fragrance_character":["citrusová","dřevitá","orientální","sladká","kořeněná","ambrová","intenzivní"],"occasion":["večer","chladnější období"],"fragrance_notes":["růžový pepř, šafrán, grep","tabák, cedr, vanilka","pačuli, olibanum (kadidlo), kašmeran, suchá ambra"],"concentration":["parfémová voda"]},"diagnostic_questions":["Pro koho vůni vybíráte a jaké vůně běžně používá?","Má být spíše svěží, květinová, sladká, dřevitá, nebo kořeněná?","Je vůně na každý den, večer, konkrétní období, nebo jako dárek?","Jak výraznou vůni a jaký rozpočet preferujete?"]}' AS JSON)),
  ('fun', 'FANN-3616307208536', 'Hugo Boss Bottled Beyond For Her', 'Ponořte se do povznášející energie s BOSS Bottled Beyond Eau de Parfum for Her – vůní spojující pivoňku a javorový sirup. Tato neodolatelná kompozice se otevírá rozkvetlou směsí pivoněk, která zachycuje zářivost a krásu této květiny.', 2080.00, 0, 1, 'fragrance', 'parfémová voda 30 ml', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/bottled-beyond-for-her/12487/24389","product_id":12487,"variant_id":24389,"ean":"3616307208536","checked_at":"2026-09-21"},"brand":"Hugo Boss","variant_label":"parfémová voda 30 ml","availability_at_check":"InStock","selection_attributes":{"category":["vůně"],"product_type":["parfémová voda"],"target_audience":["ženy"],"needs":["rozjasnění"],"finish_and_effect":["zářivý"],"fragrance_character":["květinová","gurmánská","sladká","ambrová"],"fragrance_notes":["směs pivoňky, javorový sirup","směs pivoňky, javorový sirup","směs pivoňky, javorový sirup"],"concentration":["parfémová voda"]},"diagnostic_questions":["Pro koho vůni vybíráte a jaké vůně běžně používá?","Má být spíše svěží, květinová, sladká, dřevitá, nebo kořeněná?","Je vůně na každý den, večer, konkrétní období, nebo jako dárek?","Jak výraznou vůni a jaký rozpočet preferujete?"]}' AS JSON)),
  ('fun', 'FANN-5711914172794', 'GOSH COPENHAGEN Just Click It! Volume Mascara', 'NA JEDEN KLIK Nový přírůstek do rodiny Gosh řasenek je tím nejvíc „instafriendly" kouskem. Na jedno kliknutí řasenku otevřete a během několika vteřin dodáte svým řasám objem i délku.', 329.00, 0, 1, 'makeup', 'objemová řasenka 10 ml', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/just-click-it-volume-mascara/8034/15299","product_id":8034,"variant_id":15299,"ean":"5711914172794","checked_at":"2026-09-21"},"brand":"GOSH COPENHAGEN","variant_label":"objemová řasenka 10 ml","availability_at_check":"InStock","selection_attributes":{"category":["líčení"],"product_type":["objemová řasenka"],"target_audience":["citlivá pleť nebo oči","nositelé kontaktních čoček"],"needs":["odlíčení a čištění","objem řas"],"features":["bez parfemace","Allergy Certified","veganské složení"]},"diagnostic_questions":["Jaký konkrétní efekt, krytí nebo odstín hledáte?","Má být výsledek matný, saténový, přirozený, nebo zářivý?","Potřebujete voděodolnost či celodenní výdrž?","Máte citlivé oči, pleť nebo jiné omezení?"]}' AS JSON)),
