  ('fun', 'FANN-5711914205775', 'GOSH COPENHAGEN Forever Mineral Eyeshadow Waterproof', 'Krémové stíny v sytých metalických barvách, které drží po celý den! Ne, tohle není sen, ale jde o vylepšenou verzi původních oblíbených stínů Forever Eye Shadows.', 329.00, 0, 1, 'makeup', 'minerální voděodolné stíny v tužce 1,4 g', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/forever-mineral-eyeshadow-waterproof/11742/22985","product_id":11742,"variant_id":22985,"ean":"5711914205775","checked_at":"2026-09-21"},"brand":"GOSH COPENHAGEN","variant_label":"minerální voděodolné stíny v tužce 1,4 g","availability_at_check":"InStock","selection_attributes":{"category":["líčení"],"product_type":["minerální voděodolné stíny v tužce"],"finish_and_effect":["metalický","vysoká pigmentace","dlouhotrvající","voděodolný"],"fragrance_character":["intenzivní"]},"diagnostic_questions":["Jaký konkrétní efekt, krytí nebo odstín hledáte?","Má být výsledek matný, saténový, přirozený, nebo zářivý?","Potřebujete voděodolnost či celodenní výdrž?","Máte citlivé oči, pleť nebo jiné omezení?"]}' AS JSON)),
  ('fun', 'FANN-5711914183882', 'GOSH COPENHAGEN Matte Eye Liner', 'PASTELKY PRO DOSPĚLÉ Doplňte si do své povinné výbavy odstíny, které jste si tajně přáli, ale báli jste po nich zeptat! Matné tužky na oči s krémovým složením lze po nanesení perfektně rozpracovat a vrstvit, jak ale zaschnou, nehnou se.', 249.00, 0, 1, 'makeup', 'matná tužka na oči 1,2 g', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/matte-eye-liner/8033/17870","product_id":8033,"variant_id":17870,"ean":"5711914183882","checked_at":"2026-09-21"},"brand":"GOSH COPENHAGEN","variant_label":"matná tužka na oči 1,2 g","availability_at_check":"InStock","selection_attributes":{"category":["líčení"],"product_type":["matná tužka na oči"],"finish_and_effect":["matný","vysoká pigmentace","voděodolný"],"features":["bez parfemace","Allergy Certified"]},"diagnostic_questions":["Jaký konkrétní efekt, krytí nebo odstín hledáte?","Má být výsledek matný, saténový, přirozený, nebo zářivý?","Potřebujete voděodolnost či celodenní výdrž?","Máte citlivé oči, pleť nebo jiné omezení?"]}' AS JSON)),
  ('fun', 'FANN-3346470432116', 'Guerlain Mad Eyes', 'Řasenka MAD EYES od Guerlain poskytuje řasám nebývalé rozlišení a objem: +112 %* objemu v jediném okamžiku. Řasy jsou hustší, delší a krásně natočené po dobu 24 hodin**.', 1150.00, 0, 1, 'makeup', 'řasenka pro objem a zahuštění řas', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/mad-eyes/7567/14445","product_id":7567,"variant_id":14445,"ean":"3346470432116","checked_at":"2026-09-21"},"brand":"Guerlain","variant_label":"řasenka pro objem a zahuštění řas","availability_at_check":"InStock","selection_attributes":{"category":["líčení"],"product_type":["řasenka pro objem a zahuštění řas"],"needs":["objem řas","prodloužení řas"],"finish_and_effect":["přirozený","dlouhotrvající","voděodolný"],"fragrance_character":["intenzivní"]},"diagnostic_questions":["Jaký konkrétní efekt, krytí nebo odstín hledáte?","Má být výsledek matný, saténový, přirozený, nebo zářivý?","Potřebujete voděodolnost či celodenní výdrž?","Máte citlivé oči, pleť nebo jiné omezení?"]}' AS JSON)),
  ('fun', 'FANN-3346470431621', 'Guerlain Terracotta Compact Matte Powder', 'Sluncem políbená pleť, která působí přirozeným opáleným a zdravým dojmem. Speciální složení zanechá pleť krásně zmatněnou.', 1670.00, 0, 1, 'makeup', 'matující pudr 10 g', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/terracotta-compact-matte-powder/7686/14695","product_id":7686,"variant_id":14695,"ean":"3346470431621","checked_at":"2026-09-21"},"brand":"Guerlain","variant_label":"matující pudr 10 g","availability_at_check":"InStock","selection_attributes":{"category":["líčení"],"product_type":["matující pudr"],"finish_and_effect":["matný","přirozený"]},"diagnostic_questions":["Jaký konkrétní efekt, krytí nebo odstín hledáte?","Má být výsledek matný, saténový, přirozený, nebo zářivý?","Potřebujete voděodolnost či celodenní výdrž?","Máte citlivé oči, pleť nebo jiné omezení?"]}' AS JSON)),
  ('fun', 'FANN-3346470417175', 'Guerlain KissKiss', '"Rtěnka KissKiss je dokonalou kombinací barvy a lesku a nabízí intenzivní saténový povrch s dokonalou odolností. KissKiss má jemnou, krémovou a návykovou texturu a intenzivní, rozjasňující a zářivou barvu.', 1210.00, 0, 1, 'makeup', 'krémová saténová rtěnka 3,5 g', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/kisskiss/10407/20015","product_id":10407,"variant_id":20015,"ean":"3346470417175","checked_at":"2026-09-21"},"brand":"Guerlain","variant_label":"krémová saténová rtěnka 3,5 g","availability_at_check":"InStock","selection_attributes":{"category":["líčení"],"product_type":["krémová saténová rtěnka"],"needs":["hydratace","elasticita a zpevnění","rozjasnění"],"finish_and_effect":["saténový","zářivý","dlouhotrvající"],"fragrance_character":["svěží","intenzivní"]},"diagnostic_questions":["Jaký konkrétní efekt, krytí nebo odstín hledáte?","Má být výsledek matný, saténový, přirozený, nebo zářivý?","Potřebujete voděodolnost či celodenní výdrž?","Máte citlivé oči, pleť nebo jiné omezení?"]}' AS JSON)),
  ('fun', 'FANN-6412600848502', 'Lumene CC Color Correcting Cream SPF20', 'Bright future ahead for skin caring make-up. CC Color Correcting Cream je lehký fluidní make-up se středním krytím, který redukuje zarudnutí a zdokonaluje pleť pro sjednocený a přirozeně zářivý vzhled.', 499.00, 0, 1, 'makeup', 'tónovaný pleťový CC krém 30 ml', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/cc-color-correcting-cream-spf20/11744/23000","product_id":11744,"variant_id":23000,"ean":"6412600848502","checked_at":"2026-09-21"},"brand":"Lumene","variant_label":"tónovaný pleťový CC krém 30 ml","availability_at_check":"InStock","selection_attributes":{"category":["líčení"],"product_type":["tónovaný pleťový CC krém"],"needs":["hydratace","výživa","rozjasnění","odlíčení a čištění","redukce zarudnutí","sjednocení tónu pleti"],"finish_and_effect":["přirozený","zářivý","střední krytí"],"features":["veganské složení","SPF"]},"diagnostic_questions":["Jaký konkrétní efekt, krytí nebo odstín hledáte?","Má být výsledek matný, saténový, přirozený, nebo zářivý?","Potřebujete voděodolnost či celodenní výdrž?","Máte citlivé oči, pleť nebo jiné omezení?"]}' AS JSON)),
  ('fun', 'FANN-711221983866', 'Salt & Stone Natural Deodorant Extra Strength Neroli & Basil', 'Konečně deodorant pro všechny, kteří žijí svůj život v neustálém pohybu a pro svoji pokožku chtějí jen to nejlepší z přírodních zdrojů. Značka Salt & Stone vytvořila silný přírodní deodorant formulovaný pro 24 hodinovou ochranu.', 540.00, 0, 1, 'bodycare', 'přírodní deodorant s extra účinkem 75 g', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/natural-deodorant-extra-strength-neroli-basil/10403/19994","product_id":10403,"variant_id":19994,"ean":"711221983866","checked_at":"2026-09-21"},"brand":"Salt & Stone","variant_label":"přírodní deodorant s extra účinkem 75 g","availability_at_check":"InStock","selection_attributes":{"category":["péče o tělo"],"product_type":["přírodní deodorant s extra účinkem"],"needs":["hydratace","zklidnění","regenerace","ochrana proti pocení a zápachu"],"finish_and_effect":["dlouhotrvající"],"features":["bez hliníku","přírodní původ"],"fragrance_character":["svěží","květinová","sladká"],"key_ingredients":["kyselina hyaluronová","probiotika"]},"diagnostic_questions":["Jakou potřebu pokožky nebo typ ochrany řešíte?","Je pokožka suchá či citlivá?","Preferujete parfemaci, přírodní složení nebo některé složky vynechat?","Je produkt pro běžné použití, cestování, nebo jako dárek?"]}' AS JSON)),
  ('fun', 'FANN-711221984337', 'Salt & Stone Mini Deo Set', 'Hvězda mezi deodoranty, miláček internetu Objevte sadu čtyř oceňovaných vůní deodorantů kultovní kalifornské značky SALT & STONE – perfektní způsob, jak s nimi začít, ideální dárek nebo cestovní verze rituálu, který již znáte a už nechcete jiný! Sada obsahuje čtyři deodoranty v cestovní velikosti ve variantách: Santal & Vetiver Bergamot & Hinoki Neroli & Basil Black Rose & Oud Deodoranty SALT & STONE mají přírodní složení plné pečujících látek spolu s originálními vůněmi.', 1090.00, 0, 1, 'bodycare', 'set mini deodorantů', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/mini-deo-set/11992/23337","product_id":11992,"variant_id":23337,"ean":"711221984337","checked_at":"2026-09-21"},"brand":"Salt & Stone","variant_label":"set mini deodorantů","availability_at_check":"InStock","selection_attributes":{"category":["péče o tělo"],"product_type":["set mini deodorantů"],"needs":["ochrana proti pocení a zápachu"],"features":["dárková sada","cestovní balení"],"fragrance_character":["citrusová","dřevitá"],"occasion":["dárek"],"key_ingredients":["kyselina hyaluronová","probiotika"]},"diagnostic_questions":["Jakou potřebu pokožky nebo typ ochrany řešíte?","Je pokožka suchá či citlivá?","Preferujete parfemaci, přírodní složení nebo některé složky vynechat?","Je produkt pro běžné použití, cestování, nebo jako dárek?"]}' AS JSON)),
  ('fun', 'FANN-4013162018512', 'Fenjal Intensive Body Milk', 'Tělové mléko Fenjal Intensive dodová pokožce chybějící hydrataci a výživu. Právě díky získané vlhkosti zůstane pokožka dlouhodobě příjemně uvolněná a přirozeně pružná.', 180.00, 0, 1, 'bodycare', 'tělové mléko 200 ml', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/intensive-body-milk/2038/5601","product_id":2038,"variant_id":5601,"ean":"4013162018512","checked_at":"2026-09-21"},"brand":"Fenjal","variant_label":"tělové mléko 200 ml","availability_at_check":"InStock","selection_attributes":{"category":["péče o tělo"],"product_type":["tělové mléko"],"target_audience":["suchá až velmi suchá pokožka"],"needs":["hydratace","výživa","zklidnění","regenerace","elasticita a zpevnění"],"finish_and_effect":["přirozený"],"key_ingredients":["bambucké máslo","avokádový olej"]},"diagnostic_questions":["Jakou potřebu pokožky nebo typ ochrany řešíte?","Je pokožka suchá či citlivá?","Preferujete parfemaci, přírodní složení nebo některé složky vynechat?","Je produkt pro běžné použití, cestování, nebo jako dárek?"]}' AS JSON)),
  ('fun', 'FANN-711221983880', 'Salt & Stone Natural Deodorant Extra Strength Bergamot & Hinoki', 'Konečně deodorant pro všechny, kteří žijí svůj život v neustálém pohybu a pro svoji pokožku chtějí jen to nejlepší z přírodních zdrojů. Značka Salt & Stone vytvořila silný přírodní deodorant formulovaný pro 24 hodinovou ochranu.', 540.00, 0, 1, 'bodycare', 'přírodní deodorant s extra účinkem 75 g', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/natural-deodorant-extra-strength-bergamot-hinoki/10421/20045","product_id":10421,"variant_id":20045,"ean":"711221983880","checked_at":"2026-09-21"},"brand":"Salt & Stone","variant_label":"přírodní deodorant s extra účinkem 75 g","availability_at_check":"InStock","selection_attributes":{"category":["péče o tělo"],"product_type":["přírodní deodorant s extra účinkem"],"needs":["hydratace","zklidnění","regenerace","ochrana proti pocení a zápachu"],"finish_and_effect":["dlouhotrvající"],"features":["bez hliníku","přírodní původ"],"fragrance_character":["svěží","citrusová"],"key_ingredients":["kyselina hyaluronová","probiotika"]},"diagnostic_questions":["Jakou potřebu pokožky nebo typ ochrany řešíte?","Je pokožka suchá či citlivá?","Preferujete parfemaci, přírodní složení nebo některé složky vynechat?","Je produkt pro běžné použití, cestování, nebo jako dárek?"]}' AS JSON)),
  ('fun', 'FANN-4013162025473', 'Fenjal Intensive Shower Cream', 'Sprchový krém Intensive dodává pokožce potřebnou hydrataci a výživu. Šetrně čistí pokožku a celého těla a zbavuje ji nečistot.', 150.00, 0, 1, 'bodycare', 'sprchový krém 200 ml', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/intensive-shower-cream/5315/9770","product_id":5315,"variant_id":9770,"ean":"4013162025473","checked_at":"2026-09-21"},"brand":"Fenjal","variant_label":"sprchový krém 200 ml","availability_at_check":"InStock","selection_attributes":{"category":["péče o tělo"],"product_type":["sprchový krém"],"needs":["hydratace","zklidnění","regenerace","elasticita a zpevnění","odlíčení a čištění"],"fragrance_character":["jemná"],"occasion":["každodenní použití"],"key_ingredients":["bambucké máslo","avokádový olej"]},"diagnostic_questions":["Jakou potřebu pokožky nebo typ ochrany řešíte?","Je pokožka suchá či citlivá?","Preferujete parfemaci, přírodní složení nebo některé složky vynechat?","Je produkt pro běžné použití, cestování, nebo jako dárek?"]}' AS JSON)),
  ('fun', 'FANN-8699954700450', 'Pielor Immortal Patern Hand Cream', 'Hydratační krém na ruce Pielor z kolekce Immortal Pattern intenzivně vyživuje a hydratuje pokožku. Obsahuje 5 % bambuckého másla a je obohacena o Vitamín A.', 69.00, 0, 1, 'bodycare', 'hydratační krém na ruce 30ml', CAST('{"catalog_source":{"shop":"FAnn parfumerie","url":"https://www.fann.cz/produkty/immortal-patern-hand-cream/5526/10155","product_id":5526,"variant_id":10155,"ean":"8699954700450","checked_at":"2026-09-21"},"brand":"Pielor","variant_label":"hydratační krém na ruce 30ml","availability_at_check":"InStock","selection_attributes":{"category":["péče o tělo"],"product_type":["hydratační krém na ruce"],"needs":["hydratace","výživa","regenerace"],"finish_and_effect":["bez lepivého pocitu"],"features":["SPF"],"fragrance_character":["intenzivní"],"key_ingredients":["bambucké máslo"]},"diagnostic_questions":["Jakou potřebu pokožky nebo typ ochrany řešíte?","Je pokožka suchá či citlivá?","Preferujete parfemaci, přírodní složení nebo některé složky vynechat?","Je produkt pro běžné použití, cestování, nebo jako dárek?"]}' AS JSON))
ON DUPLICATE KEY UPDATE
  `name` = VALUES(`name`), `description` = VALUES(`description`), `price` = VALUES(`price`),
  `published` = 1, `kind` = VALUES(`kind`), `variant` = VALUES(`variant`),
  `data` = VALUES(`data`), `deleted` = 0;

INSERT IGNORE INTO `product_category` (`product_id`, `category_id`)
SELECT p.`id`, c.`id` FROM `product` p JOIN `category` c
  ON c.`franchise_code` = 'fun' AND c.`syscode` = CASE p.`kind`
    WHEN 'fragrance' THEN 'perfumes' WHEN 'makeup' THEN 'makeup'
    WHEN 'skincare' THEN 'creams-and-care' WHEN 'bodycare' THEN 'creams-and-care' ELSE 'other' END
WHERE p.`franchise_code` = 'fun' AND p.`sku` LIKE 'FANN-%' AND p.`deleted` = 0;

COMMIT;

SELECT COUNT(*) AS enriched_fann_products FROM `product` WHERE `franchise_code` = 'fun' AND JSON_UNQUOTE(JSON_EXTRACT(`data`, '$.catalog_source.shop')) = 'FAnn parfumerie' AND `deleted` = 0;
